async function api(path,body,method='POST',key) {
  if(owner.active)return ownerRequest(path,body);
  let response;
  try {response=await fetch('/api/commerce'+path,{method:body===undefined?'GET':method,credentials:'same-origin',headers:body===undefined?{}:{'content-type':'application/json',...(key?{'idempotency-key':key}:{})},...(body===undefined?{}:{body:JSON.stringify(body)}),signal:AbortSignal.timeout(12000)});} catch {throw {message:t('Connection interrupted. You can retry safely.','कनेक्शन टूट गया। आप सुरक्षित रूप से फिर कोशिश कर सकते हैं।'),uncertain:true};}
  const result=await response.json();
  if(!response.ok){if(response.status===401){account=null;orders=[];nestOrders=[];applications=[];}throw {message:errorText(result.error),code:result.error,status:response.status,result};} return result;
}
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,5000);}
function show(title,body){$('#dialog').classList.toggle('signin-dialog',needsSignIn());document.body.classList.toggle('signin-open',needsSignIn());$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;ownerControls($('#dialog-body'));if(!$('#dialog').open)$('#dialog').showModal();if(needsSignIn())$('#dialog-body').querySelector('input:not([type=hidden]),button:not(:disabled),select')?.focus({preventScroll:true});}
function notice(){const n=$('#notice');if(owner.active){n.className='notice';n.textContent='Owner view · Read only · Live catalogue. Personal transactions require a member account.';return;}n.className='notice'+(!navigator.onLine?' error':'');n.textContent=!navigator.onLine?t('You are offline. Reconnect to check availability and reserve.','आप ऑफलाइन हैं। उपलब्धता देखने और बुक करने के लिए कनेक्ट करें।'):'';}
function nav(){
  const names={live:t('Live'),earn:t('Earn'),shop:t('Save'),send:t('Send')};
  for(const target of ['#desktop-nav','#mobile-nav']){
    $(target).innerHTML=Object.entries(names).map(([key,name])=>`<button data-action="${key}" ${page===key?'aria-current="page"':''}>${target==='#mobile-nav'?icon(key):''}<span>${name}</span></button>`).join('');
  }
  $('#header-language').innerHTML=languagePicker(true);
  const label=owner.active?'Owner view':account?t('Account','खाता'):t('Sign in','साइन इन');
  $('#sign-label').innerHTML=`${icon('account')}<span>${esc(label)}</span>`;
  $('#sign-label').setAttribute('aria-label',label);
  $('#sign-label').dataset.action=owner.active||account?'account':'login';
  if(['account','orders'].includes(page))$('#sign-label').setAttribute('aria-current','page');else $('#sign-label').removeAttribute('aria-current');
  document.documentElement.lang=lang;
  $('.skip').textContent=t('Skip to content','मुख्य सामग्री पर जाएँ');
  $('[data-action="close"]').setAttribute('aria-label',t('Close dialog','बंद करें'));
}
function photo(p,extra=''){const index=['groundnut_oil','mustard_oil','sunflower_oil','coconut_oil'].indexOf(p.id);const care=['detergent_pick','nia_detergent','bathsoap_pick','nia_bathsoap','toothpaste_pick','essentials_pick'].indexOf(p.id);if(!cat.preview)return `<div class="photo none ${extra}">${t('Product photo pending','उत्पाद की फोटो जल्द आएगी')}</div>`;return `<div class="photo ${index>=0?'oil':'care'} ${extra}" role="img" aria-label="${esc(t('Illustrative product image','उत्पाद का उदाहरण चित्र'))}" style="background-position:${index>=0?(index%2)*100:(care%3)*50}% ${Math.floor((index>=0?index:care)/(index>=0?2:3))*100}%"></div>`;}
function stepper(p){return `<div class="stepper"><button data-action="minus" data-id="${p.id}" aria-label="${esc(t('Remove one ','एक हटाएँ ')+title(p))}">−</button><span>${cart[p.id]||0}</span><button data-action="add" data-id="${p.id}" aria-label="${esc(t('Add one ','एक जोड़ें ')+title(p))}" ${(cart[p.id]||0)>=Math.min(10,p.available)?'disabled':''}>+</button></div>`;}
function fulfillmentToggle(){return `<div class="fulfillment-choice"><p>${t('Nothing to pay now.','अभी कुछ नहीं देना है।')}</p><div class="fulfillment-toggle" role="group" aria-label="${t('How should we fulfil your order?','सामान कैसे चाहिए?')}">${[['pickup',t('Pickup','पिकअप')],['delivery',t('Delivery','डिलीवरी')]].map(([mode,label])=>`<button type="button" data-action="fulfillment" data-id="${mode}" aria-pressed="${fulfillment===mode}" ${pending||busy||!cat.locations.some(l=>(!account||account.locationIds.includes(l.id))&&l.modes.includes(mode))?'disabled':''}>${label}</button>`).join('')}</div><p class="bag-foot">${fulfillment==='pickup'?t('Pay by UPI at pickup.','पिकअप पर UPI से भुगतान करें।'):t('Pay by UPI on delivery.','डिलीवरी पर UPI से भुगतान करें।')}</p></div>`;}
function bag(){if(owner.active)return '<section class="bag stack"><h2>Owner view</h2><p>Browse published essentials and prices. Ordering requires member sign in.</p></section>';return `<section class="bag" aria-label="${t('Your bag','आपका बैग')}"><div class="bag-head"><h2>${t('Your bag','आपका बैग')}</h2><span class="bag-count">${count()}</span></div>${count()?cat.products.filter(p=>cart[p.id]).map(p=>`<div class="bag-line"><div><strong>${esc(title(p))}</strong><small>${cart[p.id]} × ${money(p.price)}</small>${stepper(p)}</div><strong>${money(p.price*cart[p.id])}</strong></div>`).join(''):`<div class="bag-empty">${icon('bag')}<p>${t('A few essentials.<br>A little less to worry about.','कुछ ज़रूरी चीज़ें।<br>थोड़ी कम चिंता।')}</p></div>`}<div class="bag-total"><span>${t('Total','कुल')}</span><strong class="price">${money(total())}</strong></div><button class="primary full" data-action="review" ${!count()||!navigator.onLine?'disabled':''}>${t('Review your bag','अपना बैग देखें')} ${icon('arrow')}</button>${fulfillmentToggle()}<div class="how"><div><b>1</b>${t('Choose your essentials','ज़रूरी सामान चुनें')}</div><div><b>2</b>${t('Reserve your bag','अपना बैग बुक करें')}</div><div><b>3</b>${t('Scan, pay and collect','स्कैन करें, भुगतान करें और सामान लें')}</div></div></section>`;}
function languagePicker(top=false){return `<label class="language-picker ${top?'language-top':''}"><span>${t('Language','भाषा')}</span><select data-language-select aria-label="${t('Choose your language','अपनी भाषा चुनें')}">${languageOptions.map(l=>`<option value="${l.id}" lang="${l.id}" ${lang===l.id?'selected':''}>${l.label}</option>`).join('')}</select></label>`;}
function footer(){return `<footer class="footer"><span>${t('Make leaving home worth it.','घर से दूर आना सार्थक हो।')}</span><div class="footer-links"><a href="https://www.nia.one/">${t('Why Nia','निया क्यों')}</a><button class="quiet" data-action="help">${t('Help')}</button></div></footer>`;}
function shop(){if(category==='insurance')return insuranceView();const products=cat.products.filter(p=>(category==='all'||categoryId(p.category)===category)&&[p.name,p.hindi,p.category,title(p),t(saveCategories.find(c=>c.id===categoryId(p.category))?.name||p.category)].join(' ').toLowerCase().includes(search.toLowerCase()));return `<div class="intro"><div><div class="eyebrow">${t('MAKE LEAVING HOME WORTH IT.','घर से दूर आना सार्थक हो।')}</div><h1><span class="wide-title">${t('Keep more of what you earn.','अपनी कमाई में से ज़्यादा बचाएँ।')}</span><span class="phone-title">${t('Keep more of what you earn.','अपनी कमाई में से ज़्यादा बचाएँ।')}</span></h1><p class="purpose">${t('Everyday essentials. More left for you and home.','रोज़ का ज़रूरी सामान। अपने और घर के लिए ज़्यादा बचत।')}</p></div><div class="payment-note"><span class="qr-icon">${icon('qr')}</span><span>${t('Reserve now. Pay when you collect.','अभी बुक करें। सामान लेते समय भुगतान करें।')}<br><small>${t('UPI at pickup or delivery','पिकअप या डिलीवरी पर UPI')}</small></span></div></div>${saveTabs()}<div class="layout"><section><div class="results-line"><span>${products.length} ${t('essentials','ज़रूरी चीज़ें')}</span><span>${cat.preview?t('Images & pack sizes are illustrative','चित्र और पैक साइज़ उदाहरण हैं'):t('Prices checked again before you reserve','बुकिंग से पहले कीमतों की फिर जाँच होगी')}</span></div><div class="products">${products.map(p=>`<article class="product"><button class="photo-button" style="padding:0;border:0;min-height:0" data-action="detail" data-id="${p.id}" aria-label="${esc(t('View ','देखें ')+title(p))}">${photo(p)}</button><div class="product-content"><h3>${esc(title(p))}</h3><div class="pack">${esc(cat.preview?t('Pack size to be confirmed','पैक साइज़ की पुष्टि बाकी है'):p.pack)}</div><span class="stock">${p.available?t('Available to reserve','बुकिंग के लिए उपलब्ध'):t('Currently unavailable','अभी उपलब्ध नहीं')}</span><div class="buy-row"><span class="price">${money(p.price)}</span>${cart[p.id]?stepper(p):`<button class="add" data-action="add" data-id="${p.id}" ${!p.available?'disabled':''}>${t('Add','जोड़ें')} +</button>`}</div></div></article>`).join('')}</div>${products.length?'':categoryEmpty()}${footer()}</section><aside class="sidebar">${bag()}</aside></div>${count()?`<button class="mobile-bag" data-action="bag"><span>${icon('bag')} ${count()} ${t('items','चीज़ें')} · ${money(total())}</span><span>${t('View bag','बैग देखें')} →</span></button>`:''}`;}
const statusText = status => ({reserved:t('Reserved','बुक हो गया'),packed:t('Packed','पैक हो गया'),loaded:t('On the way','रास्ते में'),at_stop:t('Ready to collect','लेने के लिए तैयार'),collected:t('Collected','मिल गया'),expired:t('Reservation expired','बुकिंग का समय समाप्त'),cancelled:t('Cancelled','रद्द'),return_pending:t('Return being checked','वापसी की जाँच हो रही है'),returned:t('Returned','वापस हो गया')})[status] || status;
function ordersView(){return `<div class="page"><h1>${t('Your orders & stays','आपके ऑर्डर और नेस्ट')}</h1>${earnHistory()}${nestOrdersView()}<button data-action="refresh-orders">${t('Refresh status','स्थिति ताज़ा करें')}</button><p></p>${orders.length?orders.map(o=>`<article class="order"><div class="row"><h2>${t('Your essentials','आपका ज़रूरी सामान')}</h2><span class="badge">${esc(statusText(o.status))}</span></div><div class="code">${esc(o.pickupCode)}</div><p>${t('Show this code when you collect.','सामान लेते समय यह कोड दिखाएँ।')}<br><small>${esc(o.id)}</small></p><ul>${o.lines.map(l=>`<li>${esc(t(l.name))} × ${l.qty} · ${money(l.nia*l.qty)}</li>`).join('')}</ul><p><strong>${esc(t(o.location.name))}</strong><br>${esc(t(o.location.address))}<br>${esc(date(o.location.windowStart))} – ${esc(date(o.location.windowEnd))}</p><p>${t('Collect before','इस समय से पहले लें')}: <strong>${esc(date(o.expiresAt))}</strong></p><div class="receipt"><div class="row"><span>${t('Total','कुल')}</span><strong>${money(o.amount)}</strong></div><p>${o.refund?t('Refund recorded · see reference below','रिफंड दर्ज · संदर्भ नीचे देखें'):o.paid?t('UPI payment verified by staff','टीम ने UPI भुगतान की पुष्टि की'):t('Unpaid · Pay by UPI at handover','भुगतान बाकी · सामान लेते समय UPI से दें')}</p>${o.payment?`<small>${t('Payment reference','भुगतान संदर्भ')}: ${esc(o.payment.reference)}</small>`:''}${o.refund?`<p>${t('Refund reference','रिफंड संदर्भ')}: ${esc(o.refund.reference)} · ${money(o.refund.amount)}</p>`:''}</div><div class="order-actions">${o.status==='reserved'?`<button data-action="cancel" data-id="${o.id}">${t('Cancel reservation','बुकिंग रद्द करें')}</button>`:''}<button data-action="reorder" data-id="${o.id}">${t('Add again','फिर जोड़ें')}</button><button data-action="order-help" data-id="${o.id}">${t('Get help','मदद लें')}</button></div>${issues.filter(v=>v.orderId===o.id).map(v=>`<p class="info">${t('Help request','मदद का अनुरोध')} ${esc(v.id)} · ${esc(t(v.status))}<br>${esc(v.note)}</p>`).join('')}</article>`).join(''):`<div class="panel empty"><h2>${t('No essentials orders yet','अभी सामान का कोई ऑर्डर नहीं')}</h2><p>${t('Once you reserve, your collection code and updates appear here.','बुकिंग के बाद आपका कोड और स्थिति यहाँ दिखेंगे।')}</p><button data-action="shop">${t('Browse essentials','ज़रूरी सामान देखें')}</button></div>`}${footer()}</div>`;}
function accountView(){if(owner.active)return ownerAccountMarkup(esc);return `<div class="page"><h1>${t('Your account','आपका खाता')}</h1><section class="panel stack">${account?`<h2>${esc(t(account.name))}</h2><div class="account-actions"><button data-action="membership">${icon('account')}<span>${t('Membership status')}</span>${icon('arrow')}</button><button data-action="partners">${icon('account')}<span>${t('Partner services')}</span>${icon('arrow')}</button><button data-action="orders">${icon('orders')}<span>${t('Orders & stays','ऑर्डर और नेस्ट')}</span>${icon('arrow')}</button><button data-action="help">${icon('account')}<span>${t('Contact your Nia team','अपनी निया टीम से संपर्क करें')}</span>${icon('arrow')}</button></div>`:`<h2>${t('Welcome to Niasave','नियासेव में आपका स्वागत है')}</h2><p>${t('Sign in to reserve a Nest, order essentials and follow your updates.','बुकिंग, ऑर्डर की स्थिति और सामान लेने के लिए साइन इन करें।')}</p><button class="primary" data-action="login">${t('Member sign in','सदस्य साइन इन')}</button><button data-action="owner-login">Owner access</button><button data-action="help">${t('Contact your Nia team','अपनी निया टीम से संपर्क करें')}</button>`}<button class="quiet" data-action="recovery">${t('Changed your phone number?','फोन नंबर बदल गया है?')}</button>${account?`<button class="quiet" data-action="logout">${t('Sign out','साइन आउट')}</button>`:''}</section>${cat.preview?`<p class="info">${t('Preview accounts are examples. Sign in with your Nia membership to place real orders.','प्रीव्यू खाते उदाहरण हैं। असली प्रवेश के लिए सत्यापित खाता चाहिए।')}</p>`:''}${footer()}</div>`;}
// Public presentation only: never render a cached member, balance, order or availability here.
function entryHomepage(){return `<section class="entry-hero"><div><div class="eyebrow">NiaSave · Live. Earn. Save. Send.</div><h1>${t('Make leaving home worth it.','घर से दूर आना सार्थक हो।')}</h1><p>${t('Find a place to stay. Keep more of what you earn for you and home.','रहने की जगह खोजें। अपनी कमाई में से अपने और घर के लिए ज़्यादा बचाएँ।')}</p></div><img src="/assets/bison-sukh-cafe-workers-v1.jpg" alt="" width="1672" height="941"></section><section class="entry-services" aria-label="NiaSave"><article>${icon('live')}<h2>${t('Live')}</h2><p>${t('Your Nest. A place to begin.','आपका नेस्ट। नई शुरुआत की जगह।')}</p></article><article>${icon('earn')}<h2>${t('Earn')}</h2><p>${t('Make leaving home worth it.','घर से दूर आना सार्थक हो।')}</p></article><article>${icon('shop')}<h2>${t('Save')}</h2><p>${t('Everyday essentials. More left for you and home.','रोज़ का ज़रूरी सामान। अपने और घर के लिए ज़्यादा बचत।')}</p></article><article>${icon('send')}<h2>${t('Send')}</h2><p>${t('Keep more of what you earn.','अपनी कमाई में से ज़्यादा बचाएँ।')}</p></article></section>${footer()}`;}
$('#dialog').addEventListener('cancel',event=>{if(needsSignIn())event.preventDefault();});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&needsSignIn()&&$('#dialog').open)event.preventDefault();});
function render(){const dispose=disposeEarnMap;disposeEarnMap=()=>{};dispose();nav();notice();if(needsSignIn()){$('#content').innerHTML=entryHomepage();if(!$('#dialog').open)login();return;}document.body.classList.remove('signin-open');if(!cat)return;$('#content').innerHTML=page==='live'?liveView():page==='earn'?earnView():page==='send'?sendView():page==='shop'?shop():page==='bag'?`<div class="page"><h1>${t('Your bag','आपका बैग')}</h1>${bag()}${footer()}</div>`:page==='orders'?ordersView():accountView();ownerControls();if(page==='earn'&&!owner.active)disposeEarnMap=mountMap(mapModel(earnData),t);}
async function refresh(){entryError='';try{cat=await api('/catalogue');}catch(e){entryError=e.message;throw e;}finally{entryLoading=false;}if(owner.active){account=null;if(!['live','earn','shop','send','account'].includes(page))page='live';if(page==='earn')await loadEarn();if(page==='live'){try{await loadNests();}catch(e){nestData={offers:[],error:e.message};}}render();return;}account=cat.account?.role==='member'?cat.account:null;if(!account){render();return;}if(earnPending&&earnPending.accountId!==account?.id){earnPending=null;save('nia-earn-pending',null);}if(page==='earn')await loadEarn();if(page==='send')await loadBooks();if(nestPending&&nestPending.accountId!==account?.id){nestPending=null;save('nia-nest-pending',null);}if(pending&&pending.accountId!==account?.id){pending=null;save('nia-commerce-pending',null);}for(const [id,q] of Object.entries(account||cat.memberAuth!=='passkey'?cart:{}))if(!cat.products.some(p=>p.id===id)||!Number.isInteger(q)||q<1||q>10)delete cart[id];save('nia-commerce-bag',cart);if(page==='live'){try{await loadNests();}catch(e){nestData={offers:[],error:e.message};}}if(page==='orders'&&account){await loadMemberOrders();}render();}
async function go(next,{fromHistory=false}={}){
  next=memberPages.has(next)?next:'live';
  if(owner.active&&!['live','earn','shop','send','account'].includes(next))next='account';
  const version=++navigationVersion;
  page=next;
  if(location.hash!=='#'+next)history[fromHistory?'replaceState':'pushState'](null,'','#'+next);
  $('#dialog').close();
  if(needsSignIn()){render();return;}
  if(!cat)return;
  if(next==='earn')await loadEarn();
  if(next==='send')await loadBooks();
  if(next==='live'){try{await loadNests();}catch(e){nestData={offers:[],error:e.message};}}
  if(next==='orders'){
    if(!account){page='account';history.replaceState(null,'','#account');render();login();return;}
    try{await loadMemberOrders();}catch(e){if(version!==navigationVersion)return;toast(e.message);page='account';history.replaceState(null,'','#account');}
  }
  if(version!==navigationVersion)return;
  render();window.scrollTo(0,0);
}
function syncLocation(){const setup=takePasskeySetup(location,history);if(setup)passkeySetupToken=setup;const next=pageFromLocation();if(setup||next!==page||location.hash!=='#'+next)go(next,{fromHistory:true}).then(()=>{if(setup&&cat?.memberAuth==='passkey')login();}).catch(e=>toast(e.message));}
window.addEventListener('hashchange',syncLocation);
window.addEventListener('popstate',syncLocation);
async function finishPasskey(mode,setupToken){
  if(busy)return;busy=true;$('#dialog-body').setAttribute('aria-busy','true');
  try{await usePasskey(api,mode,setupToken);if(mode==='register')passkeySetupToken='';$('#dialog').close();await refresh();}
  catch(e){const error=$('#form-error');if(error)error.textContent=e.code?errorText(e.code):e.message;else toast(e.code?errorText(e.code):e.message);}
  finally{busy=false;$('#dialog-body').removeAttribute('aria-busy');}
}
function login(){if(!cat)return show(t('Member sign in'),`<div class="stack"><p role="status">${esc(entryLoading?t('Loading…'):entryError||t('We could not complete that request. Please try again or ask your Nia team for help.'))}</p><button class="primary" data-action="entry-retry" ${entryLoading?'disabled':''}>${t('Try again','फिर कोशिश करें')}</button><button class="quiet" data-action="owner-login">Owner access</button></div>`);if(cat.memberAuth==='password')return show(t('Member sign in'),`<form id="login-form" class="stack"><p>${t('Enter the member password from your Nia team. This phone stays signed in.','निया टीम का सदस्य पासवर्ड डालें। यह फोन साइन इन रहेगा।')}</p><label>${t('Password','पासवर्ड')}<input name="password" type="password" autocomplete="current-password" required></label><div id="form-error" class="error-inline" role="alert"></div><button class="primary" type="submit">${t('Sign in and stay signed in','साइन इन करें और साइन इन रहें')}</button></form>`+`<div class="entry-language">${languagePicker()}</div>`);if(cat.memberAuth==='passkey')return show(t('Member sign in'),passkeyMarkup({t,setup:Boolean(passkeySetupToken)})+`<div class="entry-language">${languagePicker()}</div>`);challenge='';show(t('Sign in to Niasave','नियासेव में साइन इन करें'),cat.preview?`<div class="stack"><p class="info">${t('Preview access — no real OTP, orders or payment.','प्रीव्यू प्रवेश — असली OTP, ऑर्डर या भुगतान नहीं।')}</p><button class="primary" data-action="preview-login" data-id="member">${t('Continue as preview member','प्रीव्यू सदस्य के रूप में जारी रखें')}</button></div>`:`<form id="login-form" class="stack"><p>${t('Use the phone number registered with Nia.','निया में दर्ज फोन नंबर डालें।')}</p><label>${t('Mobile number','मोबाइल नंबर')}<input name="phone" type="tel" autocomplete="tel-national" inputmode="numeric" pattern="[6-9][0-9]{9}" minlength="10" maxlength="10" placeholder="${t('10-digit mobile number','10 अंकों का मोबाइल नंबर')}" required></label><div id="form-error" class="error-inline" role="alert"></div><button class="primary" type="submit">${t('Send code','कोड भेजें')}</button><button type="button" data-action="recovery">${t('Number changed? Get help','नंबर बदल गया? मदद लें')}</button></form>`);}
function recovery(){show(t('Changed your number?','नंबर बदल गया है?'),`<form id="recovery-form" class="stack"><p>${t('Keep your member ID, orders and history. Your Nia team will verify your identity before changing account access.','आपकी सदस्य ID, ऑर्डर और इतिहास वही रहेंगे। खाता बदलने से पहले निया टीम आपकी पहचान जाँचेगी।')}</p><label>${t('Member ID','सदस्य ID')}<input name="memberId" autocomplete="off" maxlength="100" pattern="[a-zA-Z0-9_-]+" required></label><label>${t('New mobile number','नया मोबाइल नंबर')}<input name="phone" type="tel" inputmode="numeric" pattern="[6-9][0-9]{9}" maxlength="10" required></label><p><small>${t('This number is used only so the Nia team can resolve your access request.','इस नंबर का उपयोग निया टीम केवल आपकी मदद के लिए करेगी।')}</small></p><div id="form-error" class="error-inline" role="alert"></div><button class="primary">${t('Request help','मदद माँगें')}</button></form>`);}
async function review(){if(!account){login();return;}if(pending){show(t('Check your reservation','अपनी बुकिंग जाँचें'),`<p>${t('Your last request may have reached us. Retry the same request to retrieve your order without creating a duplicate.','पिछला अनुरोध पहुँच गया हो सकता है। उसी अनुरोध को फिर भेजें; दूसरा ऑर्डर नहीं बनेगा।')}</p><button class="primary full" data-action="confirm">${t('Retry safely','सुरक्षित रूप से फिर कोशिश करें')}</button><div id="form-error" class="error-inline" role="alert"></div>`);return;}
const availableLocations=cat.locations.filter(l=>account.locationIds.includes(l.id)&&l.modes.includes(fulfillment));show(t('Review your bag','अपना बैग देखें'),`<form id="review-form" class="stack"><label>${fulfillment==='pickup'?t('Where will you collect?','सामान कहाँ लेंगे?'):t('Where should we deliver?','सामान कहाँ पहुँचाएँ?')}<select name="locationId" required><option value="">${t('Choose a location','जगह चुनें')}</option>${availableLocations.map(l=>`<option value="${l.id}" ${l.id===locationId?'selected':''}>${esc(t(l.name))}</option>`).join('')}</select></label><input type="hidden" name="fulfillment" value="${fulfillment}"><p><strong>${fulfillment==='pickup'?t('Pickup','पिकअप'):t('Delivery','डिलीवरी')}</strong></p><p class="info">${t('Pay by UPI when you receive your bag. No online payment is taken. Delivery is available only at listed member locations.','बैग लेते समय UPI से भुगतान करें। ऑनलाइन भुगतान नहीं लिया जाता। डिलीवरी केवल सूची में दी सदस्य जगहों पर है।')}</p><div id="form-error" class="error-inline" role="alert"></div><button class="primary">${t('Check price & availability','कीमत और उपलब्धता जाँचें')}</button></form>`);}
async function confirm(){if(busy)return;if(!pending&&draft){pending=draft;draft=null;save('nia-commerce-pending',pending);}if(!pending)return;busy=true;const btn=$('[data-action="confirm"]');if(btn){btn.disabled=true;btn.textContent=t('Confirming…','पुष्टि हो रही है…');}try{const order=await api('/orders',pending.body,'POST',pending.key);pending=null;save('nia-commerce-pending',null);cart={};save('nia-commerce-bag',cart);await go('orders');toast(t('Reserved. Your collection code is ','बुक हो गया। आपका कोड है ')+order.pickupCode);}catch(e){if(!e.uncertain&&e.code!=='service_unavailable'&&e.code!=='save_storage_unavailable'&&e.code!=='state_conflict'){pending=null;save('nia-commerce-pending',null);}if($('#form-error'))$('#form-error').textContent=e.message;if(btn){btn.disabled=false;btn.textContent=t('Try again','फिर कोशिश करें');if(!pending){btn.dataset.action='review';btn.textContent=t('Review again','फिर जाँचें');}}}finally{busy=false;}}
function saveTabs(){return `<nav class="save-categories" aria-label="${t('Save categories','बचत की श्रेणियाँ')}">${saveCategories.map(c=>`<button data-action="category" data-id="${c.id}" aria-pressed="${category===c.id}">${icon(c.icon)}<span>${t(c.name,c.hindi)}</span></button>`).join('')}</nav>`;}
function categoryEmpty(){const c=saveCategories.find(c=>c.id===category);const isSearch=Boolean(search.trim());return `<div class="empty category-empty">${icon(c?.icon||'essentials')}<h2>${isSearch?t('No matching products','कोई उत्पाद नहीं मिला'):category==='all'?t('No essentials available yet','अभी सामान उपलब्ध नहीं है'):t('No products in this category yet','इस श्रेणी में अभी कोई उत्पाद नहीं है')}</h2><p>${isSearch?t('Try a different search or category.','दूसरा शब्द या श्रेणी चुनें।'):t('Products will appear here when they are available to order.','ऑर्डर के लिए उपलब्ध होने पर उत्पाद यहाँ दिखेंगे।')}</p><button data-action="clear-search">${t('Show all essentials','सभी सामान देखें')}</button></div>`;}
function insuranceView(){return `<div class="service-intro"><div class="eyebrow">SAVE · ${t('PROTECT WHAT YOU EARN','अपनी कमाई की सुरक्षा')}</div><h1>${t('A little more peace of mind.','थोड़ी और मन की शांति।')}</h1><p>${t('Medical and loss-of-pay insurance, alongside your everyday essentials.','रोज़ के सामान के साथ चिकित्सा और वेतन के नुकसान का बीमा।')}</p></div>${saveTabs()}<div class="service-grid">${[[t('Medical insurance','चिकित्सा बीमा'),t('Cover options for medical expenses.','चिकित्सा खर्चों के लिए बीमा के विकल्प।')],[t('Loss-of-pay insurance','वेतन के नुकसान का बीमा'),t('Cover options for eligible periods when you cannot work.','पात्र अवधि में काम न कर पाने पर बीमा के विकल्प।')]].map(([name,desc])=>`<article class="panel stack"><span class="badge">${t('Not available yet','अभी उपलब्ध नहीं')}</span><h2>${name}</h2><p>${desc}</p><p class="muted">${t('The insurer, premium, benefits, exclusions and claim process will be shown here before you can choose a policy.','पॉलिसी चुनने से पहले बीमा कंपनी, प्रीमियम, लाभ, अपवाद और दावे की प्रक्रिया यहाँ दिखेगी।')}</p><button data-action="partners" data-id="insurance">${t('View current options')}</button></article>`).join('')}</div><p class="service-foot">${t('No policy is issued and no premium is collected here yet.','अभी यहाँ पॉलिसी जारी नहीं होती और प्रीमियम नहीं लिया जाता।')}</p>${footer()}`;}
async function loadEarn(){earnError='';try{earnData=await api('/earn');applications=account?(await api('/earn/applications')).applications:[];}catch(e){earnData={jobs:[]};applications=[];earnError=e.message;}}
const applicationStatus = value => ({interested:t('Application received','आवेदन मिल गया'),contacted:t('Team contacted you','टीम ने आपसे संपर्क किया'),interview:t('Interview arranged','इंटरव्यू तय हुआ'),selected:t('Selected','चयन हुआ'),closed:t('Application closed','आवेदन बंद हुआ')})[value]||value;
function earnHistory(){
  const current=applications.filter(a=>!a.historical), previous=applications.filter(a=>a.historical);
  const card=a=>`<article class="order"><div class="row"><h3>${esc(t(a.job.title))}</h3><span class="badge">${a.historical?t('Historical record'):esc(applicationStatus(a.status))}</span></div><p>${esc(a.job.employer)} · ${esc(a.job.city)}</p>${a.historical?`<p>${t('Last recorded status')}: ${esc(applicationStatus(a.status))}</p>`:''}${a.message?`<p class="info">${esc(a.message)}</p>`:''}<small>${esc(a.id)} · ${esc(date(a.updatedAt))}</small></article>`;
  return `${earnError?`<p class="info" role="status">${esc(earnError)}</p>`:''}${applications.length?`<section class="stack"><h2>${t('Your job applications','आपके नौकरी के आवेदन')}</h2>${current.map(card).join('')}${previous.length?`<details class="panel stack earn-previous"><summary>${t('Previous applications')} (${previous.length})</summary><p>${t('Earlier records kept for reference. These are not current application updates.')}</p>${previous.map(card).join('')}</details>`:''}</section>`:''}`;
}
function earnView(){if(owner.active)return ownerEarnMarkup(earnData,earnError,{esc,money});
  const model=mapModel(earnData), mapped=model.status==='ready';
  const visible=mapped?model.jobs:cat.preview && model.status==='unavailable'?earnData.jobs:[];
  return `<div class="earn-intro row"><div class="service-intro"><div class="eyebrow">EARN · WALK2WORK</div><h1>${t('Work closer. Keep more.','पास काम करें। ज़्यादा बचाएँ।')}</h1><p>${t('Find open jobs around the Nest you live in.','जिस नेस्ट में आप रहते हैं, उसके आसपास खुली नौकरियाँ खोजें।')}</p></div><button data-action="earn">${t('Refresh status','स्थिति ताज़ा करें')}</button></div>
  ${earnError?`<p class="info" role="alert">${esc(earnError)}</p>`:''}
  <div class="earn-layout">${mapMarkup(model,t,icon)}<section class="stack earn-results" aria-label="${t('Open jobs','खुली नौकरियाँ')}"><div><div class="eyebrow">WALK2WORK</div><h2>${t('Jobs near your Nest','आपके नेस्ट के पास नौकरियाँ')}</h2><p>${mapped?t('Closest locations first','सबसे पास की जगहें पहले'):t('Verified workplace locations will help you compare your journey.','काम की जगहों की पुष्टि से आपको आने-जाने की दूरी समझने में मदद मिलेगी।')}</p></div>
  ${earnPending?`<button data-action="earn-retry">${t('Retry application safely','आवेदन सुरक्षित रूप से फिर भेजें')}</button>`:''}
  ${visible.length?visible.map((j,index)=>`<article class="panel stack earn-job" id="earn-job-${esc(j.id)}" tabindex="-1"><div class="row"><h3>${mapped?`<span class="earn-job-number">${index+1}</span>`:''}${esc(t(j.title))}</h3>${j.preview?`<span class="badge">${t('Preview')}</span>`:''}</div><p>${esc(j.employer)} · ${esc(j.city)}</p>${mapped?`<span class="earn-distance">${j.distanceKm.toFixed(1)} km · ${t('straight-line distance','सीधी रेखा में दूरी')}</span><p>${j.openPositions} ${t('open positions','खाली पद')}</p>`:''}<div class="earn-compare-cost">${mapJobDetails(j,index,model.studio,t)}</div><details class="earn-job-details"><summary>${t('Shift, requirements & apply')}</summary><p>${esc(t(j.shift))}</p><p>${esc(t(j.requirements))}</p>${jobTerms(j)?`<p>${esc(jobTerms(j))}</p>`:''}<small>${t('Apply before','इस समय से पहले आवेदन करें')}: ${esc(date(j.closesAt))}</small><button class="primary" data-action="earn-apply" data-id="${esc(j.id)}" ${applications.some(a=>a.job.id===j.id)||!navigator.onLine?'disabled':''}>${applications.some(a=>a.job.id===j.id)?t('Application received','आवेदन मिल गया'):t('Apply for this job','इस नौकरी के लिए आवेदन करें')}</button></details></article>`).join(''):`<div class="panel empty"><h3>${mapped?t('No jobs open right now','अभी कोई नौकरी खुली नहीं है'):t('Open jobs are being connected','खुली नौकरियाँ जोड़ी जा रही हैं')}</h3><p>${mapped?t('Check back for new openings around your Nest.','अपने नेस्ट के आसपास नई नौकरियों के लिए फिर देखें।'):t('Your Nia team is connecting the latest Walk2Work openings.','आपकी निया टीम Walk2Work की नई खुली नौकरियाँ जोड़ रही है।')}</p></div>`}
  </section></div><section class="stack service-panel">${earnHistory()}</section>${footer()}`;
}
async function reviewJob(id){if(!account){login();return;}if(earnPending){show(t('Check your application','अपना आवेदन जाँचें'),`<p>${t('Your last request may have reached us. Retry safely to retrieve it.','पिछला अनुरोध पहुँच गया हो सकता है। उसे पाने के लिए सुरक्षित रूप से फिर कोशिश करें।')}</p><button class="primary" data-action="earn-retry">${t('Retry application safely','आवेदन सुरक्षित रूप से फिर भेजें')}</button><div id="form-error" role="alert"></div>`);return;}const j=earnData.jobs.find(j=>j.id===id);if(!j)return;show(t('Apply for this job','इस नौकरी के लिए आवेदन करें'),`<form id="earn-form" class="stack"><h3>${esc(t(j.title))}</h3><p>${esc(j.employer)} · ${esc(j.city)}</p><p>${money(j.payMin)}–${money(j.payMax)} / ${esc(t(j.payPeriod))}</p><p>${esc(t(j.shift))}</p>${jobTerms(j)?`<p>${esc(jobTerms(j))}</p>`:''}<input type="hidden" name="jobId" value="${esc(j.id)}"><input type="hidden" name="revision" value="${esc(j.revision)}"><label><input type="checkbox" name="consent" required> ${t('Share my member details with the Nia Walk2Work team about this job. Applying does not confirm a job or a payment.','इस नौकरी के लिए मेरी सदस्य जानकारी निया Walk2Work टीम से साझा करें। आवेदन से नौकरी या भुगतान की पुष्टि नहीं होती।')}</label><button class="primary">${t('Send application','आवेदन भेजें')}</button><div id="form-error" role="alert"></div></form>`);}
async function confirmJob(){if(busy||!earnPending)return;if(earnPending.accountId!==account?.id){login();return;}busy=true;try{await api('/earn/applications',earnPending.body,'POST',earnPending.key);earnPending=null;save('nia-earn-pending',null);await go('earn');toast(t('Application received','आवेदन मिल गया'));}catch(e){if(!e.uncertain&&!['service_unavailable','save_storage_unavailable','state_conflict'].includes(e.code)){earnPending=null;save('nia-earn-pending',null);}if($('#form-error'))$('#form-error').textContent=e.message;else toast(e.message);}finally{busy=false;}}

function sendView(){if(owner.active)return ownerSendMarkup();return booksMarkup(booksData,booksMonth,account,{t,esc,money})+`<section class="panel stack books-transfer"><div class="row"><h2>${t('Send money home','घर पैसे भेजें')}</h2><span class="badge">${t('Not active yet','अभी सक्रिय नहीं')}</span></div><p>${t('Bank transfers will appear in NiaBooks once the payments-bank integration is connected.','पेमेंट्स बैंक से जुड़ने के बाद बैंक ट्रांसफ़र नियाबुक्स में दिखेंगे।')}</p><button data-action="partners" data-id="remittance">${t('View current options')}</button></section>${footer()}`;}

async function loadNests(){nestData=nestStart?await api('/nests/availability',{start:nestStart}):await api('/nests');nestStart=nestData.start;}
// Local illustrative artwork only. Jat's published studio media will replace this preview map.
const previewNestImages = {
  'std-35005': {src:'/assets/studio-bunk-lockers.jpg', width:1024, height:1024},
  'std-34696': {src:'/assets/nest-blr-demo.jpg', width:1586, height:992},
  'std-34998': {src:'/assets/nest-chk-demo.jpg', width:1536, height:1024},
};
function nestPhoto(n){
  const image=cat.preview && previewNestImages[n.studioId];
  if(!image)return `<div class="nest-placeholder">${icon('live')}<span>${t('Location photos to follow','जगह की तस्वीरें जल्द आएँगी')}</span></div>`;
  return `<div class="nest-image"><img src="${image.src}" width="${image.width}" height="${image.height}" alt="${esc(n.name)} · ${t('Illustrative shared studio with bunks and lockers','बंक और लॉकर वाले साझा स्टूडियो का उदाहरण')}" loading="lazy"><span>${t('Illustrative photo','उदाहरण चित्र')}</span></div>`;
}
function liveView(){return `<div class="service-intro"><div class="eyebrow">LIVE · ${t('MAKE LEAVING HOME WORTH IT.','घर से दूर आना सार्थक हो।')}</div><h1>${t('Your Nest. A place to begin.','आपका नेस्ट। नई शुरुआत की जगह।')}</h1><p>${t('Find a place to stay. Keep more of what you earn for you and home.','रहने की जगह खोजें। अपनी कमाई में से अपने और घर के लिए ज़्यादा बचाएँ।')}</p></div><form id="nest-search-form" class="nest-search"><label>${t('When would you like to move in?','कब आना चाहते हैं?')}<input type="date" name="start" value="${esc(nestStart)}" min="${esc(nestData?.minDate)}" max="${esc(nestData?.maxDate)}" required></label><button class="primary" type="submit">${t('Check Nests','नेस्ट देखें')}</button><p>${t('First stay: 30 days. Review the total before you reserve.','पहला निवास: 30 दिन। बुकिंग से पहले कुल राशि देखें।')}</p></form>${!owner.active&&nestPending?`<p class="info">${t('A Nest request is awaiting confirmation. Retry safely to check its result.','नेस्ट अनुरोध की पुष्टि बाकी है। नतीजा जाँचने के लिए फिर कोशिश करें।')} <button data-action="nest-confirm">${t('Check my request','मेरा अनुरोध जाँचें')}</button></p>`:''}<div class="nest-grid">${(nestData?.offers||[]).map(n=>`<article class="nest-card">${nestPhoto(n)}<div class="stack"><div><span class="eyebrow">${t('NIA NEST','निया नेस्ट')}</span><h2>${esc(n.name)}</h2></div><p class="muted">${esc(t(n.address))}</p><p>${esc(t(n.details))}</p><div><strong class="price">${money(n.rent)}</strong> <span>${t('/ 30 days','/ 30 दिन')}</span><small class="block">${t('Tax','कर')} ${money(n.tax)} · ${t('Deposit','जमा')} ${money(n.deposit)}</small></div><div class="row"><strong>${t('Total at move-in','आते समय कुल')}</strong><strong>${money(n.total)}</strong></div><span class="stock">${n.available?t('Available for your dates','आपकी तारीखों के लिए उपलब्ध'):t('No Nests for these dates','इन तारीखों के लिए नेस्ट उपलब्ध नहीं')}</span><button class="primary full" data-action="nest-review" data-id="${esc(n.studioId)}" ${!n.available||!navigator.onLine?'disabled':''}>${t('View & reserve','देखें और बुक करें')}</button></div></article>`).join('')}</div>${nestData?.offers?.length?'':`<section class="panel stack"><h2>${t('No Nests available to reserve yet','अभी बुकिंग के लिए नेस्ट उपलब्ध नहीं')}</h2><p>${esc(nestData?.error||t('Available locations and confirmed prices will appear here.','उपलब्ध जगहें और पुष्टि की गई कीमतें यहाँ दिखेंगी।'))}</p><button data-action="help">${t('Ask your Nia team','अपनी निया टीम से पूछें')}</button></section>`}${footer()}`;}
async function loadMemberOrders(){await loadEarn();orders=(await api('/orders')).orders;issues=(await api('/support')).issues;nestOrdersError='';try{nestOrders=(await api('/nests/bookings')).bookings;}catch(e){nestOrders=[];nestOrdersError=e.message;}}
function nestOrdersView(){if(nestOrdersError)return `<p class="info">${t('Nest status is temporarily unavailable.','नेस्ट की स्थिति अभी उपलब्ध नहीं है।')} ${esc(nestOrdersError)}</p>`;return nestOrders.length?`<section class="stack"><h2>${t('Your Nests','आपके नेस्ट')}</h2>${nestOrders.map(b=>`<article class="order"><div class="row"><h2>${esc(b.name)} · ${esc(b.nestId)}</h2><span class="badge">${esc(b.status==='in'?t('Moved in','आ गए'):b.status==='out'?t('Checked out','निवास समाप्त'):statusText(b.status))}</span></div><p>${esc(t(b.address))}<br>${esc(b.start)} → ${esc(b.end)}</p><p><strong>${t('Booking reference','बुकिंग संदर्भ')}: ${esc(b.id)}</strong></p>${b.status==='reserved'?`<p>${t('Meet your Nia team before the hold expires','नेस्ट रोकने का समय समाप्त होने से पहले निया टीम से मिलें')}: <strong>${esc(date(b.expiresAt))}</strong></p>`:''}<p>${t('Reserved move-in total','बुकिंग के समय आने पर कुल')}: <strong>${money(b.quote.total)}</strong><br>${b.paidAmount?`${t('Recorded by the team','टीम द्वारा दर्ज')}: ${money(b.paidAmount)} · ${esc(b.paymentReferences.join(', '))}`:t('No payment recorded. Pay by UPI with the team at move-in.','कोई भुगतान दर्ज नहीं है। आते समय टीम को UPI से भुगतान करें।')}</p><p class="muted">${t('Your reservation does not sign the agreement or check you in.','बुकिंग से समझौते पर हस्ताक्षर या चेक-इन नहीं होता।')}</p><div class="order-actions">${b.canCancel?`<button data-action="nest-cancel" data-id="${esc(b.id)}">${t('Cancel Nest reservation','नेस्ट की बुकिंग रद्द करें')}</button>`:''}<button data-action="help">${t('Ask your Nia team','अपनी निया टीम से पूछें')}</button></div></article>`).join('')}</section>`:'';}
async function reviewNest(studioId){if(!account)return login();if(nestPending)return show(t('Check your Nest request','नेस्ट का अनुरोध जाँचें'),`<p>${t('Your previous request may have reached us. Retry to retrieve its result.','पिछला अनुरोध पहुँच गया हो सकता है। नतीजा देखने के लिए फिर कोशिश करें।')}</p><button class="primary full" data-action="nest-confirm">${t('Retry safely','सुरक्षित रूप से फिर कोशिश करें')}</button>`);const body={studioId,start:nestStart};const q=await api('/nests/quote',body);nestDraft={accountId:account.id,key:crypto.randomUUID(),body:{...body,fingerprint:q.fingerprint}};show(t('Review your Nest','अपना नेस्ट देखें'),`<div class="stack"><h3>${esc(q.name)}</h3><p>${esc(t(q.address))}<br>${esc(q.start)} → ${esc(q.end)} · ${t('30 days','30 दिन')}</p><div class="receipt"><div class="row"><span>${t('Stay','निवास')}</span><strong>${money(q.rent)}</strong></div><div class="row"><span>${t('Tax','कर')}</span><strong>${money(q.tax)}</strong></div><div class="row"><span>${t('Deposit','जमा')}</span><strong>${money(q.deposit)}</strong></div><div class="row"><strong>${t('Total at move-in','आते समय कुल')}</strong><strong class="price">${money(q.total)}</strong></div></div><p>${esc(t(q.terms))}</p><p class="info">${t('Nothing to pay online. Hold for up to','ऑनलाइन भुगतान नहीं। अधिकतम')} ${q.holdHours} ${t('hours, or until the end of your move-in day if sooner. Meet the team before expiry. Agreement and check-in are completed with the team.','घंटे या आने के दिन के अंत तक, जो पहले हो। समय समाप्त होने से पहले टीम से मिलें। समझौता और चेक-इन टीम के साथ पूरा होगा।')}</p><button class="primary" data-action="nest-confirm">${t('Reserve Nest · Pay at move-in','नेस्ट बुक करें · आते समय भुगतान करें')}</button><div id="form-error" role="alert" class="error-inline"></div></div>`);}
async function confirmNest(){if(busy)return;if(!account)return login();if(!nestPending&&nestDraft){nestPending=nestDraft;nestDraft=null;save('nia-nest-pending',nestPending);}if(!nestPending)return;if(nestPending.accountId!==account.id){nestPending=null;save('nia-nest-pending',null);return;}busy=true;const btn=$('[data-action="nest-confirm"]');if(btn)btn.disabled=true;try{await api('/nests/bookings',nestPending.body,'POST',nestPending.key);nestPending=null;save('nia-nest-pending',null);await go('orders');toast(t('Nest reserved. Check your reference and hold expiry below.','नेस्ट बुक हो गया। नीचे संदर्भ और समय सीमा देखें।'));}catch(e){if(!e.uncertain&&!['service_unavailable','save_storage_unavailable','state_conflict'].includes(e.code)){nestPending=null;save('nia-nest-pending',null);$('#dialog').close();await go('live');}if($('#form-error'))$('#form-error').textContent=e.message;else toast(e.message);}finally{busy=false;if(btn)btn.disabled=false;}}

document.addEventListener('click',async event=>{const button=event.target.closest('[data-action]');if(!button)return;event.preventDefault();const action=button.dataset.action,id=button.dataset.id;try{
if(action==='owner-login')return show('Owner access',ownerLoginMarkup()+`<button class="quiet full" data-action="entry-back">${t('Member sign in')}</button>`);
if(action==='owner-exit'){exitOwner();return location.reload();}
if(owner.active&&!ownerActions.has(action))return toast('Owner view is read only.');
if(['live','earn','shop','send','bag','orders','account'].includes(action))return await go(action);

if(action==='nest-review')return await reviewNest(id);
if(action==='nest-confirm')return await confirmNest();
if(action==='nest-cancel')return show(t('Cancel your Nest reservation?','नेस्ट की बुकिंग रद्द करें?'),`<p>${t('Your hold will be released. No payment has been recorded.','आपका नेस्ट फिर उपलब्ध हो जाएगा। कोई भुगतान दर्ज नहीं है।')}</p><button class="primary full" data-action="nest-cancel-confirm" data-id="${esc(id)}">${t('Cancel Nest reservation','नेस्ट की बुकिंग रद्द करें')}</button>`);
if(action==='nest-cancel-confirm'){await api('/nests/cancel',{bookingId:id});return await go('orders');}
if(action==='entry-retry'){if(entryLoading)return;entryLoading=true;login();try{await refresh();}catch{}finally{if(needsSignIn())login();else $('#dialog').close();}return;}
if(action==='entry-back')return login();
if(action==='close'){if(needsSignIn())return;nestDraft=null;draft=null;return $('#dialog').close();}
if(action==='passkey-signin'){await finishPasskey('authenticate');return;}if(action==='login')return login();if(action==='recovery')return await openMembership(true);
if(action==='membership')return await openMembership();
if(action==='partners')return await openPartners(id);
if(action==='partner-consent'){const p=partners.find(p=>p.partnerId===id);if(p)return show(t('Review request'),partnerConsentMarkup(p,serviceContext()));return;}
if(action==='partner-withdraw')return show(t('Withdraw request'),`<p>${t('Withdrawing stops further sharing. It cannot recall records already sent.')}</p><button class="primary" data-action="partner-withdraw-confirm" data-id="${esc(id)}">${t('Withdraw request')}</button>`);
if(action==='partner-withdraw-confirm'){await api('/partners/withdraw',{referralId:id});return await openPartners();}
if(action==='language')return show(t('Choose your language','अपनी भाषा चुनें'),languagePicker());
if(action==='order-help')return show(t('Help with this order','इस ऑर्डर में मदद'),`<form id="support-form" class="stack"><input type="hidden" name="orderId" value="${esc(id)}"><label>${t('What happened?','क्या हुआ?')}<select name="kind"><option value="missing_item">${t('Missing item','सामान कम है')}</option><option value="quality">${t('Quality problem','गुणवत्ता की समस्या')}</option><option value="late">${t('Late or not ready','देर / तैयार नहीं')}</option><option value="return_refund">${t('Request a return / refund','वापसी / रिफंड का अनुरोध')}</option><option value="other">${t('Something else','कुछ और')}</option></select></label><label>${t('Tell us more (optional)','और बताएँ (ज़रूरी नहीं)')}<textarea name="note" maxlength="500"></textarea></label><p>${t('Submitting a request does not mean a refund has been approved or paid. Your Nia team will review it.','अनुरोध भेजने का मतलब रिफंड की मंज़ूरी या भुगतान नहीं है। निया टीम इसकी जाँच करेगी।')}</p><div id="form-error" class="error-inline" role="alert"></div><button class="primary">${t('Send request','अनुरोध भेजें')}</button></form>`);
if(action==='help'&&needsSignIn())return show(t('Contact your Nia team'),`<div class="stack"><p>${t('Lost access? Your Nia team will check your identity before restoring access. Your history stays with your membership.')}</p><button class="primary" data-action="entry-back">${t('Member sign in')}</button></div>`);
if(action==='help')return show(t('Your Nia team','आपकी निया टीम'),`<div class="stack"><p>${esc(t(cat.support))}</p><button data-action="books-harassment">${t('Lender harassing you?')}</button><button data-action="recovery">${t('Help with a changed phone number','बदले हुए फोन नंबर के लिए मदद')}</button></div>`);
if(action==='preview-login'){await api('/auth/preview',{role:id});$('#dialog').close();await refresh();render();return;}
if(action==='logout'){memberStatus=null;partners=[];partnerReferrals=[];planDrafts.clear();planState=null;planRequest=null;booksData=null;booksMonth='';booksRequest=null;applications=[];earnPending=null;save('nia-earn-pending',null);await api('/auth/logout',{});account=null;orders=[];nestOrders=[];nestPending=null;save('nia-nest-pending',null);cart={};pending=null;save('nia-commerce-bag',{});save('nia-commerce-pending',null);await refresh();return;}
if(action==='fulfillment'){if(pending||busy||!['pickup','delivery'].includes(id)||!cat.locations.some(l=>(!account||account.locationIds.includes(l.id))&&l.modes.includes(id)))return;fulfillment=id;if(!cat.locations.some(l=>l.id===locationId&&l.modes.includes(id)))locationId='';render();document.querySelector(`[data-action="fulfillment"][data-id="${id}"]`)?.focus({preventScroll:true});return;}
if(action==='category'){if(!categoryId(id))return;category=id;search='';render();return;}if(action==='clear-search'){search='';category='all';render();return;}
if(action==='add'||action==='minus'){const p=cat.products.find(p=>p.id===id);if(!p)return;const q=Math.min(Math.min(10,p.available),(cart[id]||0)+(action==='add'?1:-1));if(q>0)cart[id]=q;else delete cart[id];save('nia-commerce-bag',cart);render();const focus=document.querySelector(`[data-action="${action==='minus'&&!cart[id]?'add':action}"][data-id="${id}"]`);focus?.focus({preventScroll:true});return;}
if(action==='detail'){const p=cat.products.find(p=>p.id===id);return show(title(p),`${photo(p,'detail-photo')}<p>${esc(t(p.pack))}</p><p class="price">${money(p.price)}</p><p>${t('Pay at pickup or delivery. Final availability is checked when you reserve.','पिकअप या डिलीवरी पर भुगतान करें। बुकिंग के समय उपलब्धता जाँची जाती है।')}</p>${cat.preview?`<p class="info">${t('Illustrative image. Pack size and supplier details need confirmation before the pilot opens.','उदाहरण चित्र। पायलट शुरू होने से पहले पैक साइज़ और सप्लायर जानकारी की पुष्टि चाहिए।')}</p>`:''}`);}
if(action==='books-plan'){if(!account)return login();return await openPlan();}
if(action==='books-plan-save')return await savePlan();
if(action==='books-plan-reload')return await openPlan();
if(action==='books-loans')return show(t('Lower-cost loan pathway'),healthSupportDialog('loans',t)+`<button data-action="partners" data-id="lending">${t('Review request')}</button>`);
if(action==='books-harassment')return show(t('Help with lender harassment'),healthSupportDialog('harassment',t)+`<button data-action="partners" data-id="harassment_support">${t('Review request')}</button>`);
if(action==='books-add'){if(booksRequest)return await submitBooks(booksRequest.body);return show(t('Add to NiaBooks'),personalEntryForm(null,id,{t,esc}));}
if(action==='books-edit'){const entry=personalEntry(id);if(entry)return show(t('Edit your entry'),personalEntryForm(entry,entry.kind,{t,esc}));return;}
if(action==='books-remove'){const entry=personalEntry(id);if(entry)return await submitBooks({id,revision:entry.revision,remove:true});return;}
if(action==='books-refresh')return await go('send');
if(action==='books-download')return downloadBooks(booksData,booksMonth);
if(action==='books-consent'){await api('/books/consent',{enabled:id==='on'});await loadBooks();render();$('[data-action="books-consent"]')?.focus({preventScroll:true});return;}
if(action==='earn-apply')return await reviewJob(id);if(action==='earn-retry')return await confirmJob();
if(action==='review')return await review();if(action==='confirm')return await confirm();if(action==='refresh-orders')return await go('orders');
if(action==='cancel')return show(t('Cancel this reservation?','यह बुकिंग रद्द करें?'),`<p>${t('Nothing has been paid. Your reserved stock will be released.','कोई भुगतान नहीं हुआ है। बुक किया गया सामान फिर उपलब्ध हो जाएगा।')}</p><button class="primary full" data-action="cancel-confirm" data-id="${id}">${t('Cancel reservation','बुकिंग रद्द करें')}</button>`);
if(action==='cancel-confirm'){await api('/cancel',{orderId:id});await go('orders');return;}
if(action==='reorder'){const o=orders.find(o=>o.id===id);for(const l of o.lines){const p=cat.products.find(p=>p.id===l.id);if(p?.available)cart[l.id]=Math.min(l.qty,p.available,10);}save('nia-commerce-bag',cart);await go('bag');return toast(t('Added available items. Prices will be checked again.','उपलब्ध सामान जोड़ा गया। कीमतों की फिर जाँच होगी।'));}
}catch(e){if($('#dialog').open){let error=$('#dialog-body .error-inline');if(!error){error=document.createElement('p');error.className='error-inline';error.setAttribute('role','alert');$('#dialog-body').append(error);}error.textContent=e.message;}else toast(e.message);}});
document.addEventListener('input',event=>{if(event.target.matches('#books-plan-form input')){const values=Object.fromEntries(new FormData(event.target.form));planDrafts.set(currentPlanKey(),values);$('#plan-result').innerHTML=planResult(values,{t,money});if(planState?.status==='ready'&&planState.saveState!=='saving'){planState={...planState,saveState:planState.savedFields&&sameFields(fieldsFromValues(values),planState.savedFields)?'saved':'unsaved',error:null};refreshPlanStatus();}}});
document.addEventListener('submit',event=>{if(event.target.id==='books-plan-form')event.preventDefault();});
document.addEventListener('change',async event=>{if(event.target.matches('#books-entry-form [name="kind"]')){event.target.form.elements.namedItem('label').innerHTML=entryPurposeOptions(event.target.value,'',{t,esc});return;}if(event.target.matches('[data-books-month]')){booksMonth=event.target.value;render();$('[data-books-month]')?.focus({preventScroll:true});return;}if(event.target.matches('[data-language-select]')){const selector=event.target,next=selector.value;if(!validLanguage(next))return;selector.disabled=true;try{await loadLanguage(next);lang=next;save('nia-language',lang);$('#dialog').close();render();($('#dialog').open?$('#dialog [data-language-select]'):$('[data-language-select]'))?.focus({preventScroll:true});}catch{selector.value=lang;toast(t('Language could not be loaded. Check your connection and try again.','भाषा लोड नहीं हुई। कनेक्शन जाँचकर फिर कोशिश करें।'));}finally{selector.disabled=false;}}});
document.addEventListener('submit',async event=>{if(owner.active&&event.target.id!=='nest-search-form'){event.preventDefault();return;}if(!['owner-login-form','passkey-setup-form','login-form','verify-form','review-form','recovery-form','support-form','nest-search-form','earn-form','books-entry-form','member-enrol-form','member-recovery-form','partner-referral-form'].includes(event.target.id))return;event.preventDefault();const form=event.target,fields=Object.fromEntries(new FormData(form));const submit=form.querySelector('button[type=submit],button.primary');if(submit)submit.disabled=true;try{
if(form.id==='owner-login-form'){await signInOwner(fields);account=null;nestPending=null;orders=[];nestOrders=[];applications=[];page='live';history.replaceState(null,'','#live');form.reset();$('#dialog').close();await refresh();return;}
if(form.id==='passkey-setup-form'){await finishPasskey('register',passkeySetupToken);return;}
if(form.id==='member-enrol-form'){await api('/membership/enrol',{fullName:fields.fullName,preferredLanguage:lang,consent:fields.consent==='on'});await openMembership();}
if(form.id==='member-recovery-form'){await api('/membership/recovery',{oldPhone:'+91'+fields.oldPhone});show(t('Request help','मदद माँगें'),`<p>${t('Your Nia team will review the request. Your account has not changed.')}</p>`);}
if(form.id==='partner-referral-form'){const chosen=new FormData(form).getAll('fields');if(!chosen.length)throw {message:t('Choose at least one record to share.')};await api('/partners/referrals',{partnerId:fields.partnerId,consentVersion:Number(fields.consentVersion),fields:chosen,consent:fields.consent==='on'});return await openPartners();}
if(form.id==='books-entry-form'){const amountPaise=Math.round(Number(fields.amount)*100);await submitBooks({...(fields.entryId?{id:fields.entryId,revision:Number(fields.revision)}:{}),date:fields.date,kind:fields.kind,amountPaise,label:fields.label});}
if(form.id==='nest-search-form'){nestStart=fields.start;await loadNests();render();}
if(form.id==='earn-form'){if(!earnPending)earnPending={accountId:account.id,key:crypto.randomUUID(),body:{jobId:fields.jobId,revision:fields.revision,consent:fields.consent==='on'}};save('nia-earn-pending',earnPending);await confirmJob();}
if(form.id==='login-form'){if(cat.memberAuth==='password'){await api('/auth/login',{password:fields.password});$('#dialog').close();await refresh();return;}const result=await api('/auth/request',{phone:'+91'+fields.phone});challenge=result.challenge;show(t('Enter your code','अपना कोड डालें'),`<form id="verify-form" class="stack"><p>${t('If this number has access, an SMS code will arrive.','यदि इस नंबर को प्रवेश मिला है, तो SMS कोड आएगा।')}</p><label>${t('Verification code','पुष्टि कोड')}<input name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{4,8}" maxlength="8" required></label><div id="form-error" class="error-inline" role="alert"></div><button class="primary">${t('Verify & continue','पुष्टि करके आगे बढ़ें')}</button><button type="button" data-action="login">${t('Use another number / resend','दूसरा नंबर / फिर भेजें')}</button></form>`);}
if(form.id==='verify-form'){await api('/auth/verify',{challenge,code:fields.code});$('#dialog').close();await refresh();}
if(form.id==='recovery-form'){const result=await api('/recovery',{memberId:fields.memberId,newPhone:'+91'+fields.phone});show(t('Help request received','मदद का अनुरोध मिल गया'),`<p>${t('Your reference','आपका संदर्भ')}: <strong>${esc(result.id)}</strong></p><p>${t('Bring this reference and your member ID to your Nia team. Your account and orders have not changed.','यह संदर्भ और सदस्य ID लेकर निया टीम के पास जाएँ। आपका खाता और ऑर्डर नहीं बदले हैं।')}</p>`);}
if(form.id==='support-form'){await api('/support',fields);await go('orders');toast(t('Your help request has been saved.','आपकी मदद का अनुरोध सहेजा गया।'));}
if(form.id==='review-form'){locationId=fields.locationId;fulfillment=fields.fulfillment;const body={locationId,fulfillment,lines:Object.entries(cart).map(([id,qty])=>({id,qty}))};const q=await api('/quote',body);const request={...body,fingerprint:q.fingerprint};show(t('Confirm your reservation','अपनी बुकिंग की पुष्टि करें'),`<div class="stack"><ul class="review-lines">${q.lines.map(l=>`<li>${esc(t(l.name))} × ${l.qty} · ${money(l.nia*l.qty)}</li>`).join('')}</ul><div class="row"><strong>${t('Total due at handover','सामान लेते समय कुल देना है')}</strong><strong class="price">${money(q.amount)}</strong></div><p><strong>${esc(t(q.location.name))}</strong><br>${esc(t(q.location.address))}<br>${t('Collect before','इस समय से पहले लें')} ${esc(date(q.expiresAt))}</p><p class="info">${t('A reservation is not a payment. Scan the team’s UPI QR when you receive your bag. Staff will check the receipt before handing it over.','बुकिंग भुगतान नहीं है। बैग लेते समय टीम का UPI QR स्कैन करें। सामान देने से पहले टीम रसीद जाँचेगी।')}</p><button class="primary" data-action="confirm">${t('Reserve · Pay at handover','बुक करें · लेते समय भुगतान करें')}</button><div id="form-error" class="error-inline" role="alert"></div></div>`);draft={accountId:account.id,key:crypto.randomUUID(),body:request};}
}catch(e){const error=$('#form-error');if(error)error.textContent=e.message;else toast(e.message);}finally{if(submit)submit.disabled=false;}});
window.addEventListener('online',()=>{notice();render();});window.addEventListener('offline',()=>{notice();render();});
(async()=>{if(location.hash!=='#'+page)history.replaceState(null,'','#'+page);try{await loadLanguage(lang);}catch{lang='en';}try{await restoreOwner();}catch(e){toast(e.message);}render();await refresh();if(passkeySetupToken&&cat.memberAuth==='passkey'&&!owner.active)login();else if(needsSignIn())login();})().catch(e=>{entryLoading=false;entryError=e.message;render();if(needsSignIn())login();});

let statusRead=false;
setInterval(async()=>{if(needsSignIn()||statusRead||busy||document.hidden||!navigator.onLine||$('#dialog').open||!['orders','earn'].includes(page)||document.activeElement?.matches('input,select,textarea,button'))return;statusRead=true;try{if(page==='orders'&&account)await loadMemberOrders();else if(page==='earn')await loadEarn();if(page==='send')await loadBooks();render();}catch{toast(t('Could not refresh status. Try again.','स्थिति ताज़ा नहीं हुई। फिर कोशिश करें।'));}finally{statusRead=false;}},30000);
